import json
from docx import Document

def replace_in_text(text, data):
    for key, value in data.items():
        placeholder = f'{{{{{key}}}}}'
        if placeholder in text:
            text = text.replace(placeholder, str(value))
    return text

def process_parent(parent, data):
    for p in parent.paragraphs:
        # Simple replacement in paragraph text
        for key, value in data.items():
            placeholder = f'{{{{{key}}}}}'
            if placeholder in p.text:
                p.text = p.text.replace(placeholder, str(value))

    for t in parent.tables:
        for r in t.rows:
            for c in r.cells:
                process_parent(c, data)

# Loading data
with open('employee_data.json', 'r') as f:
    data = json.load(f)

doc = Document('offer_letter_template.docx')

# Handle relocation logic first
# Since markers are in paragraphs, we can find them in doc.paragraphs
# (assuming they are not in a table)
paragraphs = list(doc.paragraphs)
start_p = -1
end_p = -1
for i, p in enumerate(paragraphs):
    if '{{IF_RELOCATION}}' in p.text:
        start_p = i
    if '{{END_IF_RELOCATION}}' in p.text:
        end_p = i

if start_p != -1 and end_p != -1:
    if data.get('RELOCATION_PACKAGE') == 'Yes':
        doc.paragraphs[start_p].text = doc.paragraphs[start_p].text.replace('{{IF_RELOCATION}}', '')
        doc.paragraphs[end_p].text = doc.paragraphs[end_p].text.replace('{{END_IF_RELOCATION}}', '')
    else:
        for i in range(end_p, start_p - 1, -1):
            p = doc.paragraphs[i]._element
            p.getparent().remove(p)

# Replace all placeholders recursively
process_parent(doc, data)

doc.save('/root/offer_letter_filled.docx')
